<script setup lang="ts">
import {onMounted,ref,watch,computed} from 'vue'
import type {AppointmentSummary,FeePreview} from '../../api/workspace-types'
import {useUnsaved} from '../../composables/useUnsaved'
import {useRoute} from 'vue-router'
import type {components} from '@adc/contracts'
import {createProtectedClient} from '../../api/protected'
import {ApiFailure,prepareCommand,UnknownOutcomeError,type PreparedCommand} from '../../api/http'
import {useViewScope} from '../../stores/view-scope'
import {useAuthenticationStore} from '../../stores/authentication'
const api=createProtectedClient(),auth=useAuthenticationStore(),route=useRoute(),canIssue=computed(()=>route.meta.readOnly!==true && auth.canAccess('CASHIER','invoiceAppointment')),canRead=computed(()=>auth.canAccess('CASHIER','getInvoice') || auth.canAccess('HEADQUARTERS','getInvoice')),appointments=ref<AppointmentSummary[]>([]),next=ref<string|null>(null),appointmentId=ref(typeof route.query.appointmentId==='string'?route.query.appointmentId:''),invoiceId=ref(typeof route.query.invoiceId==='string'?route.query.invoiceId:''),invoice=ref<components['schemas']['InvoiceView']|null>(null),confirmed=ref(false),busy=ref(false),unknown=ref(false),error=ref(''),notice=ref('');let pending:PreparedCommand|undefined
const preview=ref<FeePreview|null>(null),previewBusy=ref(false);let previewVersion=0
useUnsaved(()=>confirmed.value,()=>unknown.value)
function printInvoice(){window.print()}
async function failed(failure:unknown){error.value=failure instanceof ApiFailure?({COMPLETED_VISIT_REQUIRED:'就诊尚未完成，不能生成费用凭据。',ACTUAL_TREATMENT_REQUIRED:'没有有效实际治疗项目，请核对本次诊疗。',INVALID_INVOICE_SOURCE:'费用来源关联不一致，未生成新凭据。'}[failure.code]??`未完成：${failure.message}`):'服务暂不可用。';if(failure instanceof ApiFailure && [401,403].includes(failure.status)){invoice.value=null;preview.value=null;confirmed.value=false;appointments.value=[];await auth.ensure()}}
let listVersion=0
const listBusy=ref(false)
const scope=useViewScope();watch(()=>scope.clinic,()=>{appointments.value=[];next.value=null;list()})
async function list(more=false){if(!canIssue.value || !auth.canAccess('CASHIER','listAppointments'))return;const version=++listVersion;listBusy.value=true;if(!more){appointments.value=[];next.value=null}try{const query=new URLSearchParams({role:'CASHIER',status:'COMPLETED',limit:'100'});if(scope.clinic)query.set('clinic_id',scope.clinic);if(more && next.value)query.set('cursor',next.value);const page=await api.get<{items:components['schemas']['AppointmentView'][];next_cursor:string|null}>(`/api/v1/workspace/appointments?${query}`);if(version!==listVersion)return;appointments.value=more?[...appointments.value,...page.items]:page.items;next.value=page.next_cursor}catch(failure){if(version===listVersion)await failed(failure)}finally{if(version===listVersion)listBusy.value=false}}
async function choose(id:string){if(pending||busy.value)return;const version=++previewVersion;appointmentId.value=id;confirmed.value=false;invoice.value=null;notice.value='';error.value='';preview.value=null;previewBusy.value=true;try{const data=await api.get<FeePreview>('/api/v1/appointments/'+encodeURIComponent(id)+'/fee-preview');if(version===previewVersion)preview.value=data}catch(failure){if(version===previewVersion)await failed(failure)}finally{if(version===previewVersion)previewBusy.value=false}}
async function execute(){if(!pending)return;busy.value=true;error.value='';try{const result=await api.execute<components['schemas']['InvoiceView']>(pending);invoice.value=result.data;invoiceId.value=result.data.invoice_id;notice.value='费用凭据已生成，可查看原单或打印；此状态不代表已付款。';pending=undefined;unknown.value=false;confirmed.value=false;await list()}catch(failure){if(failure instanceof UnknownOutcomeError){unknown.value=true;error.value='结果确认中，请保留当前页面并重新确认办理结果。'}else{pending=undefined;unknown.value=false;await failed(failure)}}finally{busy.value=false}}
async function issue(){if(pending || !confirmed.value || !preview.value || previewBusy.value)return;pending=prepareCommand('invoiceAppointment','POST',`/api/v1/appointments/${encodeURIComponent(appointmentId.value)}/invoice`,{});await execute()}
async function read(){if(pending)return;busy.value=true;error.value='';try{invoice.value=await api.get(`/api/v1/invoices/${encodeURIComponent(invoiceId.value)}`)}catch(failure){invoice.value=null;await failed(failure)}finally{busy.value=false}}
onMounted(async()=>{await list();if(appointmentId.value&&canIssue.value)await choose(appointmentId.value);if(invoiceId.value&&canRead.value)await read()})
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">BILLING WORKSPACE</p><h1>{{canIssue?'费用凭据工作区':'费用凭据查阅'}}</h1><p class="muted">核对已完成就诊的实际治疗费用，再确认开具。</p></div><button v-if="invoice" @click="printInvoice">打印费用凭据</button></div><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status" class="success-message">{{notice}}</p><div v-if="unknown" class="confirmation-summary"><p>结果确认中。重新确认会找回同一原单。</p><button :disabled="busy" @click="execute">重新确认办理结果</button></div>
 <section v-if="canIssue&&auth.canAccess('CASHIER','listAppointments')" class="surface"><div class="page-heading"><h2>已完成 · 待开费用凭据</h2><button :disabled="busy||unknown" @click="list()">刷新队列</button></div><p v-if="listBusy" role="status">正在读取待开凭据队列…</p><ul class="queue-list"><li v-for="item in appointments" :key="item.appointment_id"><span><strong>{{item.patient_name||'摘要未取得'}}</strong><small>{{item.patient_number}} · {{item.clinic_name}} · {{item.dentist_name}}</small></span><button :disabled="busy||unknown" @click="choose(item.appointment_id)">核对费用 →</button></li></ul><p v-if="!appointments.length&&!error&&!listBusy" class="empty-state">暂无待开凭据的已完成就诊。</p><button v-if="next" :disabled="busy||unknown" @click="list(true)">加载更多待办</button></section>
 <p v-if="previewBusy" role="status">正在读取本次就诊费用…</p><section v-if="preview&&!invoice" class="surface"><div class="page-heading"><div><h2>{{preview.patient_name}} · 费用预览</h2><p>{{preview.patient_number}} · {{preview.clinic_name}}</p></div><span class="status-badge">待核对</span></div><div class="table-scroll"><table><thead><tr><th>实际治疗</th><th>标准单位数</th><th>历史单价</th><th>小计</th></tr></thead><tbody><tr v-for="(line,i) in preview.items" :key="i"><td>{{line.treatment_name}}</td><td>{{line.standard_units}}</td><td>{{line.unit_price}}</td><td>{{line.subtotal}}</td></tr></tbody></table></div><p class="invoice-total">合计 ¥{{preview.total_amount}}</p><label><input v-model="confirmed" type="checkbox" :disabled="busy||unknown">已核对就诊对象、实际治疗和逐项费用</label><div class="dialog-actions"><button class="compact-primary" :disabled="!confirmed||busy||unknown||previewBusy" @click="issue">确认生成唯一费用凭据</button></div></section>
 <details v-if="canRead"><summary>查阅已有费用凭据</summary><form @submit.prevent="read"><fieldset :disabled="busy||unknown"><label>费用凭据标识<input v-model="invoiceId" required pattern="[1-9][0-9]*"></label><button>读取原费用凭据</button></fieldset></form></details>
 <section v-if="invoice" class="invoice-document"><h2>费用凭据 {{invoice.invoice_number}}</h2><p>就诊 {{invoice.appointment_id}} · 开具时间 {{new Date(invoice.issued_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}（北京时间）</p><div class="table-scroll"><table><caption>开具时冻结的逐项费用</caption><thead><tr><th>序号</th><th>治疗项目</th><th>标准单位数</th><th>历史单价</th><th>小计</th></tr></thead><tbody><tr v-for="line in invoice.items" :key="line.line_number"><td>{{line.line_number}}</td><td>{{line.treatment_name}}</td><td>{{line.standard_units}}</td><td>{{line.unit_price}}</td><td>{{line.subtotal}}</td></tr></tbody></table></div><p class="invoice-total">费用合计：{{invoice.total_amount}}</p><p>费用凭据 ID：{{invoice.invoice_id}}</p></section></section></template><style scoped>.invoice-total{font-size:24px;font-weight:700;text-align:right}.invoice-document{margin:24px 0}</style>